//https://iquilezles.org/articles/distfunctions2d/
float sdTriangleIsosceles( in vec2 p, in vec2 q )
{
    p.x = abs(p.x);
    vec2 a = p - q*clamp( dot(p,q)/dot(q,q), 0.0, 1.0 );
    vec2 b = p - q*vec2( clamp( p.x/q.x, 0.0, 1.0 ), 1.0 );
    float s = -sign( q.y );
    vec2 d = min( vec2( dot(a,a), s*(p.x*q.y-p.y*q.x) ),
                  vec2( dot(b,b), s*(p.y-q.y)  ));
    return -sqrt(d.x)*sign(d.y);
}

void renderTriangleParticle(vec2 viewPortCoords, particle p, inout vec4 result)
{
    float t = abs((float(p.idx)-float(gNumParticles)/2.0f) / float(gNumParticles));
    vec3 c1 = 1.5*palette(t 
            , vec3(0.5),vec3(0.5),vec3(1.0),vec3(0.0, 0.1, 0.2) );
    vec3 c2 = 1.5*palette(t + 0.2f
            , vec3(0.5),vec3(0.5),vec3(1.0),vec3(0.0, 0.1, 0.2) );
    float myDepth = length(c1 + c2);
    if (myDepth > gDepth)
    {
        float visibilityRadius = 1.f;

        vec2 virp = (viewPortCoords - p.pos.xy);

        vec2 d = -normalize(p.vel);
        vec2 rp = vec2(d.y * virp.x - d.x * virp.y, d.x * virp.x + d.y * virp.y);


        float base = 2.0f;
        float height = 8.0f;
        float dist = sdTriangleIsosceles(rp, vec2(base,height));
        if (dist < visibilityRadius)
        {
            result = vec4(mix( c1, c2, rp.y / (1.5*height)), 0.0f);
            gDepth = myDepth;
        }  
    } 
}

void renderCircle(vec2 viewPortCoords, particle p, inout vec4 result)
{
    // sample code
    float t = abs((float(p.idx)-float(gNumParticles)/2.0f) / float(gNumParticles));
    vec3 plCol = 1.2*malouPalette(t);
            //1.0*palette(0.4f + 1.0f * t 
            //, vec3(0.5),vec3(0.5),vec3(1.0),vec3(0.0, 0.1, 0.2) );
    float myDepth = length(plCol);
    if (myDepth > gDepth)
    {
        float visibilityRadius = 4.f;

        vec2 virp = (viewPortCoords - p.pos.xy);

        float dist = length(virp);
        if (dist < visibilityRadius)
        {
            result = vec4(plCol, 0.0f);
            gDepth = myDepth;
        }  
    } 
}

void renderParticle(vec2 viewPortCoords, particle p, inout vec4 result)
{    
    // sample code
#if BOIDS
    renderTriangleParticle(viewPortCoords, p, result);
#else
    renderCircle(viewPortCoords, p, result);
#endif
}

vec4 sampleScene(vec2 viewPortCoords)
{
    float t = iTime * 0.25f;
    vec3 prev = hash(uvec3(13u,7u,29u + uint(t)));
    vec3 curr = hash(uvec3(13u,7u,29u + uint(t) + 1u));
    vec3 baseCol = mix(prev, curr, fract(t));

    //vec3 baseCol = mix(prev, curr, fract(t)); //vec3(77, 136, 213)/255.0f;
    vec4 result = vec4(baseCol * 0.05f,0.0f);  

    uint count = 0u;

    ivec2 currentTileCoords = ivec2(int(viewPortCoords.x) / int(TILE_W), int(viewPortCoords.y) / int(TILE_H));

    // for each tile within range
    for (int y = -1; y <= 1; y++)
    {
        for (int x = -1; x <= 1; x++)
        {
            //if tile is close enough, loop over particles in it.
            ivec2 tileCoords = currentTileCoords + ivec2(x,y);

            //edges
            if (tileEdgeInteraction(tileCoords)) continue;

            ivec2 tileCoordsC = ivec2(tileCoords.x, tileCoords.y) + ivec2(NUM_TILES_X,0) * int(CURR_BUFFER);
            uint startIdx = vec4ToUint(texelFetch(iChannel2, tileCoordsC, 0));

            ivec2 tileCoordsB = ivec2(tileCoords.x, tileCoords.y) + ivec2(NUM_TILES_X,0) * int(COPIED_B_BUFFER_OFFSET);
            uint tcount = vec4ToUint(texelFetch(iChannel2, tileCoordsB, 0));

            for (uint i = startIdx; i < startIdx + tcount; i++)
            {
                // retrieve the particle
                uint ix = i % MEMORY_WIDTH;
                uint iy = i / MEMORY_WIDTH;
                uint particleIndex = vec4ToUint(texelFetch(iChannel3, ivec2(ix, iy), 0));
                if (particleIndex == INVALID_PARTICLE_IDX) continue; // invalid particle

                particle p = loadParticle(particleIndex);
                renderParticle(viewPortCoords, p, result);    
            }
        }
    }

    return result;
}

