bool debugdrawBBuffer(inout vec4 fragColor, in vec2 fragCoord)
{
    if (uint(fragCoord.x) < (NUM_TILES_X * 2u) && uint(fragCoord.y) < NUM_TILES_Y)
    {     
        uint numParticles = LOAD_UINT(CURR_NUM_PARTICLES_STORE_LOC);

        vec2 newCoord = vec2(fragCoord.x, fragCoord.y);
        vec4 rgba = texelFetch(iChannel1, ivec2(fragCoord), 0);
        uint u = vec4ToUint(rgba);
        fragColor = mix(vec4(0,0,1,0), vec4(1,0,0,0), float(u) / ((1.0f/2000.0f) * float(numParticles)));

        return true;
    }
    return false;
}

bool tileEdgeWrap(inout ivec2 tileCoords)
{
    if (tileCoords.x < 0) tileCoords.x += int(NUM_TILES_X);
    if (tileCoords.x >= int(NUM_TILES_X)) tileCoords.x -= int(NUM_TILES_X);
    if (tileCoords.y < 0) tileCoords.y += int(NUM_TILES_Y);
    if (tileCoords.y >= int(NUM_TILES_Y)) tileCoords.y -= int(NUM_TILES_Y);
    return false;
}

bool tileEdgeCull(inout ivec2 tileCoords)
{
    return (tileCoords.x < 0) 
        || (tileCoords.x >= int(NUM_TILES_X))
        || (tileCoords.y < 0)
        || (tileCoords.y >= int(NUM_TILES_Y));
}

