// any state to be accumulated can be global:
float gMaxRadius = 10.0f;  // Maximum distance for interactions
float gMaxSpeed = 60.0f;
uint gNumNeighbors = 0u;  // Number of neighbors for current particle
vec2 gAlignment = vec2(0.0);  // Accumulated alignment vector
vec2 gCohesion = vec2(0.0);   // Accumulated position for cohesion
vec2 gSeparation = vec2(0.0); // Accumulated separation vector

