void particleInteraction(inout particle p1, particle p2)
{
#if BOIDS
    float dist = distanceFunc(p1,p2);

    // Check if within MAX_RADIUS and not self
    if (dist < gMaxRadius && dist > 0.0f)
    {
        vec2 diff = p2.pos - p1.pos;
        vec2 dir = diff / dist;   // Normalized direction vector 


        // Accumulate alignment (average velocity of neighbors)
        gAlignment += p2.vel;

        // Accumulate cohesion (average position of neighbors)
        gCohesion += p2.pos;

        // Accumulate separation (avoid close neighbors)
        gSeparation -= dir / dist;

        // Increment neighbor count
        gNumNeighbors++;
    }
#endif
}

void edgeRepel(inout particle p);
vec2 getRandomDirection(uint idx)
{
    vec3 randomVec = hash(uvec3(idx, idx + uint(iFrame), idx * 131u)); // Generate random values based on the particle index
    float angle = randomVec.x * 2.0f * 3.14159f; // Random angle in radians
    return vec2(cos(angle), sin(angle));        // Unit vector in random direction
}
void particleUpdate(inout particle p)
{
#if BOIDS
    vec2 alignment = vec2(0.0);
    vec2 cohesion = vec2(0.0);
    vec2 separation = vec2(0.0);

    if (gNumNeighbors > 0u)
    {
        alignment = normalize(gAlignment / float(gNumNeighbors)) * 30.0f; // Scale alignment force
        cohesion = normalize((gCohesion / float(gNumNeighbors)) - p.pos) * 32.0f; // Toward average position
        separation = normalize(gSeparation) * 75.0f; // Stronger repulsion force
    }

    // Wander force based on particleIndx
    float wanderStrength = 20.0f; // Adjust as needed
    vec2 wander = getRandomDirection(p.idx) * wanderStrength;

    // Combine boid forces
    vec2 boidForce = wander + alignment + cohesion + separation;

    // Apply boid forces to the velocity
    p.vel += boidForce * DELTA_TIME;
#endif
    // max speed
    if (dot(p.vel,p.vel) > gMaxSpeed*gMaxSpeed)
    {
        p.vel = normalize(p.vel) * gMaxSpeed;
    }

    // perform the final move
    p.pos += p.vel * DELTA_TIME;
}

void initParticle(uint index, inout particle p)
{
    // what happens if a new particle spawns:
    // ...

    // e.g.: spawn on top of mouse
    float spawnRange = 30.0f;
    vec3 h1 = hash(uvec3(index + 13u, index + 5u, index * 11u));
    p.pos = screenToViewport(iMouse.xy).xy + normalize(2.0*h1.xy-1.0f) * h1.zz * spawnRange;

    p.vel = normalize(p.pos - screenToViewport(iMouse.xy).xy) * gMaxSpeed;
}

