bool gIsThreadActive = true;
vec4 storeParticle(uint idx, storedParticle sp)
{
    uint offsetInStoredParticleStruct = 0u;
    if (isPixelResponsibleFor(GET_VARIABLE_STORE(idx, offsetInStoredParticleStruct)))
    {
        gIsThreadActive = false;
        return sp.posVel;
    }

    return INVALID_PARTICLE;
}

vec4 storeParticle(particle pIn)
{
    storedParticle sp = packParticle(pIn);
    return storeParticle(pIn.idx, sp);
