vec4 handleResizing()
{
    vec4 data = LOAD(RESIZE_STORE_LOC);
    bool isResizing = (data.r < 1.0f) || (data.z > 0.0f) || (data.w > 0.0f);
    return vec4(1.0f, isResizing, 0.0f, 0.0f);
}

bool isParticleMemory(uvec2 memCoord);

void mainImage( out vec4 result, in vec2 memCoord )
{
    if (isPixelResponsibleFor(RESIZE_STORE_LOC))
    {
        result = handleResizing();
        return;
    }

    // record number of particles and spawn if any when left mouse is clicked.
    uint numCurrParticles = RESTART ? NUM_INITIAL_PARTICLES : LOAD_UINT(CURR_NUM_PARTICLES_STORE_LOC);
    uint numSpawnedParticles = 0u;

#if SPAWN_ON_CLICK
    if (!RESTART && iMouse.z > 0.0f)
    {
        numSpawnedParticles += SPAWN_COUNT;
    }

#endif

    if (isParticleMemory(uvec2(memCoord)))
    {
        uint index = getParticleIndexByCoord(memCoord);
        if (RESTART)
        {
            storedParticle p = initializeInitialParticle(index);     
            result = storeParticle(index, p);
            if (!gIsThreadActive) return;
        }
        else
        {    
            // UPDATE PARTICLE
            particle p;

            // if we are a new particle: initialize instead of updating
            if (index >= numCurrParticles && index < numCurrParticles + numSpawnedParticles)
            {
                initParticle(index, p);
                storedParticle sp = packParticle(p);

                // we'll wait till next frame to start interacting.
                // because other particles can't see the new ones yet here.
                result = storeParticle(index, sp);
                if (!gIsThreadActive) return;
            }
            else
            {
                p = loadParticle(index);
            }

            uint tileID = getTileID(p.pos);
            uint myID = index;

            ivec2 currentTileCoords = ivec2(tileID % NUM_TILES_X, tileID / NUM_TILES_X);

            // for each tile within range
            for (int y = -1; y <= 1; y++)
            {
                for (int x = -1; x <= 1; x++)
                {
                    ivec2 tileCoords = currentTileCoords + ivec2(x,y);

                    //edge behaviour
                    if (tileEdgeInteraction(tileCoords)) continue;

                    // get the count in that tile last frame  (B)
                    ivec2 tileCoordsB = tileCoords + ivec2(NUM_TILES_X,0) * int(COPIED_B_BUFFER_OFFSET);
                    uint prevCount = vec4ToUint(texelFetch(iChannel2, tileCoordsB, 0));

                    ivec2 tileCoordsC = tileCoords + ivec2(NUM_TILES_X,0) * int(PREV_BUFFER);
                    uint nOffset = vec4ToUint(texelFetch(iChannel2, tileCoordsC, 0));

                    // iterate over those (D) and get them from previous frame (A)
                    for (uint i = nOffset; i < nOffset + prevCount; i += 1u)
                    {
                        uint ix = i % MEMORY_WIDTH;
                        uint iy = i / MEMORY_WIDTH;
                        uint particleIndex = vec4ToUint(texelFetch(iChannel3, ivec2(ix, iy), 0));

                        if (particleIndex == myID || particleIndex == INVALID_PARTICLE_IDX) continue; // invalid particle

                        particle p2 = loadParticle(particleIndex);
                        particleInteraction(p, p2);
                    }  
                }
            }       

            vec4 mouse = vec4(screenToViewport(iMouse.xy), screenToViewport(iMouse.zw));
            mouseInteraction(p, mouse);

            particleUpdate(p);

            // handle window edges
            edgeInteraction(p);

            // storeparticle
            result = storeParticle(p);
            if (!gIsThreadActive) return;
        }
    }

    if (isPixelResponsibleFor(CURR_NUM_PARTICLES_STORE_LOC))
    {
        result = uintToVec4(numCurrParticles + numSpawnedParticles);
        return;
    }

    if (isPixelResponsibleFor(PREV_NUM_PARTICLES_STORE_LOC))
    {
        result = uintToVec4(numCurrParticles);
        return;
    }

    if (isPixelResponsibleFor(SETTINGS_CHANGED_STORE_LOC))
    {
        result = uintToVec4(uint(SETTINGS_CHANGED));
        return;
    } 

    if (isPixelResponsibleFor(TILE_W_STORE_LOC))
    {
        result = uintToVec4(TILE_W);
        return;
    }

    if (isPixelResponsibleFor(TILE_H_STORE_LOC))
    {
        result = uintToVec4(TILE_H);
        return;
    }

    if (isPixelResponsibleFor(NUM_TILES_X_STORE_LOC))
    {
        result = uintToVec4(NUM_TILES_X);
        return;
    }

    if (isPixelResponsibleFor(NUM_TILES_Y_STORE_LOC))
    {
        result = uintToVec4(NUM_TILES_Y);
        return;
    }

    if (isPixelResponsibleFor(TILES_PER_BUCKET_STORE_LOC))
    {
        result = uintToVec4(TILES_PER_BUCKET);
        return;
    }   
}

float wrappedDistance(particle p1, particle p2)
{
    vec2 delta = abs(p2.pos - p1.pos);
    vec2 wrapped_delta = vec2(VIEWPORT_W, VIEWPORT_H) - delta;
    return length(min(delta, wrapped_delta));
}

float customDistance(particle p1, particle p2)
{
    return distance(p1.pos, p2.pos);
}

uint getTileID(vec2 vpCoords)
{
    uint tileX = (uint(vpCoords.x)) / TILE_W;
    uint tileY = (uint(vpCoords.y)) / TILE_H;
    return tileX + tileY * NUM_TILES_X;
}

uint getParticleIndexByCoord(vec2 memCoord)
{
    uint index = uint(memCoord.y) * uint(VIEWPORT_W) + uint(memCoord.x) - PARTICLE_MEM_START;
    index /= STORED_PARTICLE_SIZE;
    return index;
}

storedParticle initializeInitialParticle(uint id)
{
    // some random numbers based on the id
    vec3 h1 = hash(uvec3(id + 13u, id + 5u, id * 11u));
    vec3 h2 = hash(uvec3(id + 17u, id + 9u, id * 13u));

    // tile id
    uint countPerTile = NUM_INITIAL_PARTICLES / NUM_TILES;
    uint tileID = id / countPerTile;    
    storedParticle particle;

    vec2 tileStart;
    tileStart.x = float(tileID % NUM_TILES_X) * float(TILE_W);
    tileStart.y = float(tileID / NUM_TILES_X) * float(TILE_H);

    vec2 offset = h1.xy * vec2(TILE_W, TILE_H);

    particle.posVel.xy = tileStart + offset; // random start position

    particle.posVel.zw = normalize(vec2(2.0f * (h2.xy - 0.5f))) * gMaxSpeed; // random start velocity
    return particle;
}

void edgeWrap(inout particle p)
{
    if (p.pos.x < 0.0f) p.pos.x += float(VIEWPORT_W);
    if (p.pos.x >= float(VIEWPORT_W)) p.pos.x -= float(VIEWPORT_W);;

    if (p.pos.y < 0.0f) p.pos.y += float(VIEWPORT_H);
    if (p.pos.y >= float(VIEWPORT_H)) p.pos.y -= float(VIEWPORT_H);
}

void edgeRepel(inout particle p)
{
    // adjust velocity
    float repelDistance = 100.0f;
    float repelStrength = 200.0f;
    if (p.pos.x < repelDistance)
    {
        float t = 1.0f-((p.pos.x) / repelDistance);
        p.vel.x += repelStrength * (t*t) * DELTA_TIME;
    }
    if (p.pos.x >= float(VIEWPORT_W) - repelDistance)
    {
        float t = ((p.pos.x - (float(VIEWPORT_W) - repelDistance)) / repelDistance);
        p.vel.x -= repelStrength * (t*t) * DELTA_TIME;
    }
    if (p.pos.y < repelDistance)
    {
        float t = 1.0f-((p.pos.y) / repelDistance);
        p.vel.y += repelStrength * (t*t) * DELTA_TIME;

    }
    if (p.pos.y >= float(VIEWPORT_H) - repelDistance)
    {
        float t = ((p.pos.y -(float(VIEWPORT_H) - repelDistance)) / repelDistance);
        p.vel.y -= repelStrength * (t*t) * DELTA_TIME;
    }

    // stay in frame
    if (p.pos.x < 0.0f)
    {
        p.pos.x = -p.pos.x; 
    }
    if (p.pos.x >= float(VIEWPORT_W))
    {
        p.pos.x = float(VIEWPORT_W) - (p.pos.x - float(VIEWPORT_W)); 
    }
    if (p.pos.y < 0.0f)
    {
        p.pos.y = -p.pos.y; 
    }
    if (p.pos.y >= float(VIEWPORT_H))
    {
        p.pos.y = float(VIEWPORT_H) - (p.pos.y - float(VIEWPORT_H)); 
    }

}

void edgeBounce(inout particle p)
{
    if (p.pos.x < 0.0f)
    {
        p.vel.x = -p.vel.x;
        p.pos.x = -p.pos.x; 
    }
    if (p.pos.x >= float(VIEWPORT_W))
    {
        p.vel.x = -p.vel.x;
        p.pos.x = float(VIEWPORT_W) - (p.pos.x - float(VIEWPORT_W)); 
    }
    if (p.pos.y < 0.0f)
    {
        p.vel.y = -p.vel.y;
        p.pos.y = -p.pos.y; 
    }
    if (p.pos.y >= float(VIEWPORT_H))
    {
        p.vel.y = -p.vel.y;
        p.pos.y = float(VIEWPORT_H) - (p.pos.y - float(VIEWPORT_H)); 
    }
}

