// hash
vec3 hash( uvec3 x )
{  
    //https://www.shadertoy.com/view/4lXyWN

    //multiply large prime value first.
    uint k = 1103515245U;
    x*= k;
    //mix x, y, z values.
    //Without shift operator, x, y and z value become same value.
    x = ((x>>2u)^(x.yzx>>1u)^x.zxy)*k;

    return (vec3(x)*(1.0/float(0xffffffffU)));
}

vec4 uintToVec4(uint originalValue) {
    vec4 result;
    uint byte0 = originalValue & 0xFFu;
    uint byte1 = (originalValue >> 8u) & 0xFFu;
    uint byte2 = (originalValue >> 16u) & 0xFFu;
    uint byte3 = (originalValue >> 24u) & 0xFFu;
    result.x = float(byte0) / 255.0;
    result.y = float(byte1) / 255.0;
    result.z = float(byte2) / 255.0;
    result.w = float(byte3) / 255.0;
    return result;
}

uint vec4ToUint(vec4 inputValue) {
    uint byte0 = uint(inputValue.x * 255.0);
    uint byte1 = uint(inputValue.y * 255.0);
    uint byte2 = uint(inputValue.z * 255.0);
    uint byte3 = uint(inputValue.w * 255.0);
    uint result = byte0 | (byte1 << 8) | (byte2 << 16) | (byte3 << 24);
    return result;
}

