vec3 malouPalette(in float t)
{
    t *= 2.0f;
    if (t < 0.25f) return mix(vec3(19.0f,42.0f,19.0f) / 255.0f, vec3(49.0f,87.0f,44.0f) / 255.0f, (t * 4.0f));
    if (t < 0.50f) return mix(vec3(49.0f,87.0f,44.0f) / 255.0f, vec3(79.0f,119.0f,45.0f) / 255.0f, (t - 0.25f) * 4.0f);
    if (t < 0.75f) return mix(vec3(79.0f,119.0f,45.0f) / 255.0f, vec3(144.0f,169.0f,85.0f) / 255.0f, (t - 0.5f) * 4.0f);
    if (t <= 1.0f) return mix(vec3(144.0f,169.0f,85.0f) / 255.0f, vec3(236.0f, 243.0f, 158.0f) / 255.0f, (t - 0.75f) * 4.0f);
    return vec3(0.0f);
}

