void mainImage( out vec4 result, in vec2 memCoord )
{
    // early out.
    if (RESTART)
    {
        if (uint(memCoord.x) >= NUM_TILES_X * NUM_BUFFERS && uint(memCoord.y) >= NUM_TILES_Y) return;
        // because of how we initalized it. this is the case
        uint countPerTile = NUM_INITIAL_PARTICLES / NUM_TILES;
        uvec2 currCoord = uvec2(uint(memCoord.x) % uint(NUM_TILES_X), memCoord.y) + uvec2(NUM_TILES_X,0) * CURR_BUFFER;

        result = uintToVec4(countPerTile);
        return;
    }
    else
    {
        uint tileID = uint(memCoord.y) * uint(NUM_TILES_X) + uint(memCoord.x) % uint(NUM_TILES_X);

        uint count = 0u;
        // for each neighbouring tile
        for (uint n = 0u; n < 9u; n++)
        {
            ivec2 tileCoords = ivec2(uint(memCoord.x) % uint(NUM_TILES_X), memCoord.y) + g_tileOffset[n];

            //neighbour wrapping behaviour
            if (tileEdgeInteraction(tileCoords)) continue;

            // get the count in that tile last frame  (B)
            ivec2 tileCoordsB = tileCoords + ivec2(NUM_TILES_X,0) * int(PREV_BUFFER);
            uint prevCount = vec4ToUint(texelFetch(iChannel1, tileCoordsB, 0));

            // C-buffer calc offset
            ivec2 tileCoordsC = tileCoords + ivec2(NUM_TILES_X,0) * int(PREV_BUFFER);
            uint nOffset = vec4ToUint(texelFetch(iChannel2, tileCoordsC, 0));

            // iterate over those (D) and get them from current frame (A)
            for (uint i = nOffset; i < nOffset + prevCount; i++)
            {
                // retrieve the particle
                uint ix = i % uint(iChannelResolution[3].x);
                uint iy = i / uint(iChannelResolution[3].x);
                uint particleIndex = vec4ToUint(texelFetch(iChannel3, ivec2(ix, iy), 0));
                if (particleIndex == INVALID_PARTICLE_IDX) continue; // invalid particle

                vec2 pos = LOAD(GET_VARIABLE_STORE(particleIndex,0u)).xy;
                uint pTileID = getTileID(pos);
                if (tileID == pTileID)
                {
                    count++;
                }
            }
        }


        // add any new particles if relevant
        uint numCurrParticles = LOAD_UINT(CURR_NUM_PARTICLES_STORE_LOC);
        uint numPrevParticles = LOAD_UINT(PREV_NUM_PARTICLES_STORE_LOC);

        for (uint i = numPrevParticles; i < numCurrParticles; i++)
        {
            uvec2 bufferAPos = GET_VARIABLE_STORE(i, 0u);
            vec4 posVel = texelFetch(iChannel0, ivec2(bufferAPos.x, bufferAPos.y), 0);

            uint pTileID = getTileID(posVel.xy);
            if (tileID == pTileID)
            {
                count++;
            }
        }

        uvec2 currCoord = uvec2(uint(memCoord.x) % uint(NUM_TILES_X), memCoord.y) + uvec2(NUM_TILES_X,0) * CURR_BUFFER;
        if (isPixelResponsibleFor(currCoord))
        {
            result = uintToVec4(count);
            return;
        }
    }

    uvec2 prevCoord = uvec2(uint(memCoord.x) % uint(NUM_TILES_X), memCoord.y) + uvec2(NUM_TILES_X,0) * PREV_BUFFER;
    uint previousCount = vec4ToUint(texelFetch(iChannel1, ivec2(prevCoord), 0));
    if (isPixelResponsibleFor(prevCoord))
    {
        result = uintToVec4(previousCount);
        return;
    }
}

