// Buffer C counts in each bucket of tiles, what index a specific tile starts on.
// this way in combination with the count of particles in a tile in buffer B.
// we define a range in buffer D, where we will store the particles of this tile for 
// easy lookup in the image and in buffer A.

uint getBucketFromTile(uint tile);
uint getNthTileInBucket(uint bucket, uint n);
uint getBucketOffset(uint bucket);

void mainImage( out vec4 result, in vec2 memCoord )
{
    // early out. we want to store 2 of our own buffers + the current B buffer
    if (uint(memCoord.x) >= (NUM_TILES_X * (NUM_BUFFERS + 1u)) || uint(memCoord.y) >= NUM_TILES_Y) return;

    ivec2 tileCoords = ivec2(uint(memCoord.x) % uint(NUM_TILES_X),uint(memCoord.y) );
    uint tileID = uint(tileCoords.y) * NUM_TILES_X + uint(tileCoords.x);

    // copy B-buffer : happens always regardless of frame -- store in the 3rd buffer
    // so we can reuse the CURR_ and PREV_ macros for actual C-buffer accessing.
    if (uint(memCoord.x) >= NUM_TILES_X * COPIED_B_BUFFER_OFFSET)
    {
        ivec2 tileCoordsB = tileCoords + ivec2(NUM_TILES_X,0) * int(CURR_BUFFER);
        uint count = vec4ToUint(texelFetch(iChannel1, tileCoordsB, 0));

        result = uintToVec4(count);
        return;
    }

    uint b = getBucketFromTile(tileID);
    uint offset = getBucketOffset(b);
    for (uint n = 0u; n < TILES_PER_BUCKET; n++)
    {
        uint t = getNthTileInBucket(b, n);
        if (t == tileID) // don't count own tile, we want to know the start
        {
            break;
        }

        uint tx = t % NUM_TILES_X;
        uint ty = t / NUM_TILES_X;

        ivec2 tileCoordsB = ivec2(tx, ty) + ivec2(NUM_TILES_X,0) * int(CURR_BUFFER);
        uint tCount = vec4ToUint(texelFetch(iChannel1, tileCoordsB, 0));
        offset += tCount; 
    }

    uvec2 currCoord = uvec2(uint(memCoord.x) % uint(NUM_TILES_X), memCoord.y) + uvec2(NUM_TILES_X,0) * CURR_BUFFER;
    if (isPixelResponsibleFor(currCoord))
    {
        result = uintToVec4(offset);
        return;
    }    

    // copy over previous offsets
    uvec2 prevCoord = uvec2(uint(memCoord.x) % uint(NUM_TILES_X), memCoord.y) + uvec2(NUM_TILES_X,0) * PREV_BUFFER;
    uint prevOffset = vec4ToUint(texelFetch(iChannel2, ivec2(prevCoord), 0));
    if (isPixelResponsibleFor(prevCoord))
    {
        result = uintToVec4(prevOffset);
        return;
    }  
}

uint getBucketOffset(uint bucket)
{
    return bucket * MAX_INDICES_PER_BUCKET;
}

uint getBucketFromTile(uint tile)
{
    //bijection (x,y) -> i
    uint tileX = tile % NUM_TILES_X;
    uint tileY = tile / NUM_TILES_X;
    uint diagonalIndex = (((NUM_TILES_X + tileX) - tileY) % NUM_TILES_X) * NUM_TILES_Y + tileY;


    uint bucketIdx = diagonalIndex / TILES_PER_BUCKET;
    return bucketIdx;
}

uint getNthTileInBucket(uint bucket, uint n)
{
    //bijection i -> (x,y)
    uint diagonalIdx = bucket * TILES_PER_BUCKET + n;
    uint tileX = ((diagonalIdx / NUM_TILES_Y) + (diagonalIdx % NUM_TILES_Y)) % NUM_TILES_X;
    uint tileY = (diagonalIdx % NUM_TILES_Y);

    uint tile = tileY * NUM_TILES_X + tileX;
    return tile;
}

// buffer D, contains the sorted list of particles, per tile, based on the count in B and the offset in C.

// returns false if tile should be culled
bool tileEdgeWrap(inout ivec2 tileCoords);
bool tileEdgeCull(inout ivec2 tileCoords);
bool tileEdgeInteraction(inout ivec2 tileCoords)
{
#if WRAP
    return tileEdgeWrap(tileCoords);
#else
    return tileEdgeCull(tileCoords);
#endif
}

