uint getNthTileInBucket(uint bucket, uint n);

void mainImage( out vec4 result, in vec2 memCoord )
{        
    uint threadIdx = uint(memCoord.x) + uint(memCoord.y) * MEMORY_WIDTH;
    if (threadIdx > MAX_INDICES_PER_BUCKET * (NUM_TILES / TILES_PER_BUCKET))
    {
        result = uintToVec4(INVALID_PARTICLE_IDX);
        return;
    }

    if (RESTART)
    {
        uint bucketIdx = threadIdx / MAX_INDICES_PER_BUCKET;
        uint bucketOffset = (threadIdx % MAX_INDICES_PER_BUCKET);

        uint countPerTile = NUM_INITIAL_PARTICLES / NUM_TILES;
        if (countPerTile > 0u)
        {
            uint nthTile = bucketOffset / countPerTile;  
            uint tileOffset = bucketOffset % countPerTile;
            uint tile = getNthTileInBucket(bucketIdx,nthTile);

            if (tileOffset < countPerTile)
            {
                uint particleIdx = countPerTile * tile + tileOffset;
                result = uintToVec4(particleIdx);
                return;
            }
        }
    }
    else
    {        
        uint bucketIdx = threadIdx / MAX_INDICES_PER_BUCKET;

        // search to find which tile we are in the bucket!
        uint prevTile = getNthTileInBucket(bucketIdx,0u);
        uint prevTOffset = bucketIdx * MAX_INDICES_PER_BUCKET;

        for (uint n = 1u; n < TILES_PER_BUCKET; n++)
        {
            uint t = getNthTileInBucket(bucketIdx,n);
            ivec2 tileCoordsC = ivec2(t % NUM_TILES_X, t / NUM_TILES_X) + ivec2(NUM_TILES_X,0) * int(CURR_BUFFER);
            uint tOffset = vec4ToUint(texelFetch(iChannel2, tileCoordsC, 0));

            if (tOffset > threadIdx)
            {
                break;
            }

            prevTile = t;
            prevTOffset = tOffset;
        }

        uint tileID = prevTile;

        ivec2 currentTileCoord = ivec2(tileID % NUM_TILES_X, tileID / NUM_TILES_X);
        uint count = prevTOffset;

        // for each neighbouring tile
        for (uint n = 0u; n < 9u; n++)
        {
            ivec2 tileCoords = currentTileCoord + g_tileOffset[n];
            if (tileEdgeInteraction(tileCoords)) continue;

            // get the count in that tile last frame  (B)
            ivec2 tileCoordsB = tileCoords + ivec2(NUM_TILES_X,0) * int(PREV_BUFFER);
            uint prevCount = vec4ToUint(texelFetch(iChannel1, tileCoordsB, 0));

            // C-buffer calc offset
            ivec2 tileCoordsC = tileCoords + ivec2(NUM_TILES_X,0) * int(PREV_BUFFER);
            uint nOffset = vec4ToUint(texelFetch(iChannel2, tileCoordsC, 0));

            // iterate over those (D) and get them from current frame (A)
            for (uint i = nOffset; i < nOffset + prevCount; i++)
            {
                // retrieve the particle
                uint ix = i % MEMORY_WIDTH;
                uint iy = i / MEMORY_WIDTH;

                uint particleIndex = vec4ToUint(texelFetch(iChannel3, ivec2(ix, iy), 0));
                if (particleIndex == INVALID_PARTICLE_IDX) continue; // invalid particle

                vec2 pos = LOAD(GET_VARIABLE_STORE(particleIndex,0u)).xy;
                uint pTileID = getTileID(pos);                

                if (tileID == pTileID)
                {
                    if (count++ == threadIdx)
                    {
                        result = uintToVec4(particleIndex);
                        return;
                    }
                }
            }
        }

        // add any new particles if relevant
        uint numCurrParticles = LOAD_UINT(CURR_NUM_PARTICLES_STORE_LOC);
        uint numPrevParticles = LOAD_UINT(PREV_NUM_PARTICLES_STORE_LOC);

        for (uint i = numPrevParticles; i < numCurrParticles; i++)
        {
            uvec2 bufferAPos = GET_VARIABLE_STORE(i, 0u);
            vec4 posVel = texelFetch(iChannel0, ivec2(bufferAPos.x, bufferAPos.y), 0);

            uint pTileID = getTileID(posVel.xy);
            if (tileID == pTileID)
            {
                if (count++ == threadIdx)
                {
                    result = uintToVec4(i);
                    return;
                }
            }
        }        
    }
    result = uintToVec4(INVALID_PARTICLE_IDX);
}

